# v2.2: audit/Fix2_Report.docx — per item before (v2.1, git tag v2-prefix) | after (v2.2 rebuild) | numbers changed;
# pre-registered vs actual outcomes; all variants (sensitivity/all_variants.csv); rebuild checks; independent re-audit scores
# (audit/reaudit_fix2/scores.csv, written by the independent agent). Run from analysis/ after the rebuild and the re-audit.
suppressMessages({ library(data.table); library(officer); library(flextable) })
cfg <- yaml::read_yaml(Sys.getenv("P6_CONFIG", "config.yaml")); ROOT <- cfg$paths$root; AUD <- file.path(cfg$paths$paper_root, "audit")
K2 <- readRDS(file.path(ROOT, "results_text", "key_numbers.rds"))
K1 <- jsonlite::fromJSON(paste(system2("git", c("-C", shQuote(ROOT), "show", "v2-prefix:results_text/key_numbers.json"), stdout = TRUE), collapse = "\n"))
dt <- function(x) as.data.table(x)
f1 <- function(x, d = 1) formatC(as.numeric(x), format = "f", digits = d)
sg <- function(x, d = 1) { x <- as.numeric(x); paste0(ifelse(x >= 0, "+", "−"), formatC(abs(x), format = "f", digits = d)) }
E <- function(K, s, m = "d_freq", p = "far") dt(K$ens_changes)[scenario == s & period == p & metric == m]
T25 <- function(K, st) { x <- dt(K$copula_T); x[T_ref == 25 & estimator == "bernstein" & set == st] }
EXW <- function(K, s) { x <- dt(K$exposure_graded); x[district == "Potohar (all units)" & scenario == s & period == "far", dE_wheat_pct] }
RC <- function(K, s, p, col = "pct_robust") { x <- dt(K$robust_cells_pct); if (!col %in% names(x)) return(NA_real_); x[scenario == s & period == p][[col]] }
MS <- function(K, pat, s) { x <- dt(K$model_set_sensitivity); x[grepl(pat, set, fixed = TRUE) & scenario == s] }
acc <- dt(K2$qdm_acceptance)[binding == TRUE]
a_ <- function(st, v, col) acc[stage == st & variable == v][[col]]
ov <- dt(K2$selection_overlap); pe2 <- dt(K2$qdm_pooling_effect); pe1 <- dt(K1$qdm_pooling_effect)
rp <- dt(K2$rp_rule_comparison)[set == "Baseline (1985–2014)" & T_ref == 25]
STAB <- dt(K2$rank_stability)[weighting == "entropy" & selected == TRUE]
rb <- readLines(file.path(ROOT, "logs", "rebuild_v22.log"), warn = FALSE)
read_scores <- function(p) { x <- readLines(p, encoding = "UTF-8")[-1]; x <- x[nzchar(x)]   # criterion names may contain unquoted commas
  m <- regmatches(x, regexec("^(.*),([0-9]+),([0-9.]+),\"?(.*?)\"?$", x, perl = TRUE))
  rbindlist(lapply(m, function(z) data.table(Criterion = z[2], Max = as.integer(z[3]), Score = as.numeric(z[4]), Justification = gsub("\"\"", "\"", z[5])))) }
scores <- if (file.exists(file.path(AUD, "reaudit_fix2", "scores.csv"))) read_scores(file.path(AUD, "reaudit_fix2", "scores.csv")) else NULL
total <- if (file.exists(file.path(AUD, "reaudit_fix2", "total.csv"))) fread(file.path(AUD, "reaudit_fix2", "total.csv")) else NULL

# ---- 1. per item ----
ITEMS <- data.table(
  Item = c("1 Direction words", "2 Return-period duration rule", "3 Bias correction (QDM)", "4 GCM ranking stability", "5 FDR on projection maps", "6 Paths, warnings, DEVIATIONS"),
  Before = c("Directional words typed by hand; no number trace for the results text.",
             "Counting estimator used D ≥ d_ref (continuous); copulas used F_D(d_ref): different events.",
             "QDM with an unstandardised ±1-month pooled window (deviation D13); plain split not used for acceptance.",
             paste0("Equal-weight compromise programming, single full-sample ranking: ", paste(K1$top_models, collapse = ", "), "."),
             "Cells hatched at ≥ 80 % agreement and Wilcoxon p < 0.05, no multiplicity control.",
             "9 code lines with absolute paths; 12 warning suppressions; DEVIATIONS numbers typed."),
  After = c(paste0("Words generated by wording.R with pre-set bands; ", nrow(fread(file.path(ROOT, "results_text", "Number_Trace.csv"))), " numbers logged, number-trace check 0 unmatched."),
            paste0("One rule: k = round(d_ref) whole months; D ≥ k (count) and F_D(k − 0.5) (copulas). Baseline 25-yr event D ≥ ", K2$ref_events$k[2], " months."),
            paste0("QDM per calendar month (methodology III-E), primary; S1 standardised and S2 unstandardised pooled windows as sensitivities. Pre-registered criteria: A ",
                   if (K2$qdm_acceptance_primary$pass_A_all) "met" else paste0("FAILED for ", paste(K2$qdm_acceptance_primary$failed_A, collapse = ", ")), ", B ", if (isTRUE(K2$qdm_acceptance_primary$pass_B)) "met" else "FAILED", "; primary kept."),
            paste0("Entropy weights, ", K2$n_boot, "-replicate moving-block bootstrap, selection by P(top 10): ", paste(K2$top_models, collapse = ", "), "."),
            "BH FDR (α = 0.05) across the cells of each map; hatched only if p_BH < 0.05 and agreement ≥ 80 %; same mask for binary exposure; BH across the 5 districts.",
            paste0("0 absolute paths (17_check_paths.R); 0 suppressions, ", format(K2$n_warnings_logged, big.mark = ","), " warnings logged and explained (5 types); DEVIATIONS.md generated from key numbers.")),
  `Numbers changed` = c(
    "No number changed by this item (wording only).",
    paste0("Baseline 25-yr Bernstein T: ", f1(rp[estimator == "bernstein", T_old_rule]), " yr (old rule) → ", f1(rp[estimator == "bernstein", T_new]), " yr; parametric ", f1(rp[estimator == "parametric", T_old_rule]), " → ", f1(rp[estimator == "parametric", T_new]), "; count ", f1(rp[estimator == "count", T_old_rule]), " → ", f1(rp[estimator == "count", T_new]), " (same fits)."),
    paste0("P mean |median monthly bias| (plain split): raw ", f1(a_("raw", "pr", "A_mean_abs")), "% → primary ", f1(a_("primary", "pr", "A_mean_abs")), "% (S1 ", f1(a_("S1", "pr", "A_mean_abs")), "%, S2 ", f1(a_("S2", "pr", "A_mean_abs")), "%). Far-future ΔP: ",
           sg(pe1[scenario == "ssp245", dP_pooled]), "/", sg(pe1[scenario == "ssp585", dP_pooled]), "% (v2.1 pooled) → ", sg(pe2[scenario == "ssp245", dP_primary]), "/", sg(pe2[scenario == "ssp585", dP_primary]), "% (raw NEX ", sg(pe2[scenario == "ssp245", dP_raw]), "/", sg(pe2[scenario == "ssp585", dP_raw]), "%)."),
    paste0("Overlap with v2.1 set ", ov[comparison == "v2.1 primary set", n_common], "/10 (out ", ov[comparison == "v2.1 primary set", dropped], ", in ", ov[comparison == "v2.1 primary set", added], "). P(top 10) of the selected models ", f1(min(STAB$p_top10), 2), "–", f1(max(STAB$p_top10), 2), "."),
    paste0("Robust cells, far: ", f1(RC(K2, "ssp245", "far", "pct_robust_noFDR")), "/", f1(RC(K2, "ssp585", "far", "pct_robust_noFDR")), "% without FDR → ", f1(RC(K2, "ssp245", "far")), "/", f1(RC(K2, "ssp585", "far")), "% with FDR; mid SSP5-8.5 ", f1(RC(K2, "ssp585", "mid", "pct_robust_noFDR")), "% → ", f1(RC(K2, "ssp585", "mid")), "%."),
    "No result number changed (warnings now visible; DEVIATIONS regenerated)."))

# ---- 2. headline findings v2.1 vs v2.2 ----
HL <- rbindlist(lapply(c("ssp245", "ssp585"), function(s) { lab <- c(ssp245 = "SSP2-4.5", ssp585 = "SSP5-8.5")[[s]]
  rbind(data.table(Finding = paste0("Δ drought frequency, far (%-pt), ", lab), v21 = E(K1, s)$wmean, v22 = E(K2, s)$wmean, rob21 = E(K1, s)$robust, rob22 = E(K2, s)$robust),
        data.table(Finding = paste0("Δ P, far (%), ", lab), v21 = E(K1, s, "d_P")$wmean, v22 = E(K2, s, "d_P")$wmean, rob21 = E(K1, s, "d_P")$robust, rob22 = E(K2, s, "d_P")$robust),
        data.table(Finding = paste0("Δ ET0, far (%), ", lab), v21 = E(K1, s, "d_ET0")$wmean, v22 = E(K2, s, "d_ET0")$wmean, rob21 = E(K1, s, "d_ET0")$robust, rob22 = E(K2, s, "d_ET0")$robust),
        data.table(Finding = paste0("Δ duration, far (months), ", lab), v21 = E(K1, s, "d_D")$wmean, v22 = E(K2, s, "d_D")$wmean, rob21 = E(K1, s, "d_D")$robust, rob22 = E(K2, s, "d_D")$robust),
        data.table(Finding = paste0("Δ severity, far, ", lab), v21 = E(K1, s, "d_S")$wmean, v22 = E(K2, s, "d_S")$wmean, rob21 = E(K1, s, "d_S")$robust, rob22 = E(K2, s, "d_S")$robust),
        data.table(Finding = paste0("25-yr event T_AND far (yr, Bernstein), ", lab), v21 = T25(K1, paste(lab, "far"))$T_and, v22 = T25(K2, paste(lab, "far"))$T_and, rob21 = NA, rob22 = NA),
        data.table(Finding = paste0("Frequency-weighted wheat exposure, far (%), ", lab), v21 = EXW(K1, s), v22 = EXW(K2, s), rob21 = NA, rob22 = NA),
        data.table(Finding = paste0("All-models set Δ frequency far (%-pt), ", lab), v21 = MS(K1, "all models", lab)$d_freq, v22 = MS(K2, "all models", lab)$d_freq, rob21 = MS(K1, "all models", lab)$robust, rob22 = MS(K2, "all models", lab)$robust)) }))
HL <- rbind(data.table(Finding = "25-yr event T_AND baseline (yr, Bernstein)", v21 = T25(K1, "Baseline (1985–2014)")$T_and, v22 = T25(K2, "Baseline (1985–2014)")$T_and, rob21 = NA, rob22 = NA), HL)
HL[, change := v22 - v21][, rel_change_pct := 100 * (v22 / v21 - 1)]
HL[, `Sign changed` := fifelse(sign(v21) != sign(v22), "YES", "no")]
HL[, `Robustness changed` := fifelse(is.na(rob21) | is.na(rob22), "", fifelse(rob21 != rob22, paste0("YES (", fifelse(rob22, "now robust", "no longer robust"), ")"), "no"))]
HL[, `Magnitude change ≥ 20 %` := fifelse(abs(rel_change_pct) >= 20, "YES", "no")]
HLo <- HL[, .(Finding, `v2.1` = f1(v21), `v2.2` = f1(v22), `Change` = sg(change), `Relative (%)` = sg(rel_change_pct, 0), `Sign changed`, `Robustness changed`, `Magnitude change ≥ 20 %`)]
fwrite(HL, file.path(AUD, "Fix2_headline_changes.csv"))

# ---- 3. pre-registered vs actual ----
PR <- data.table(
  Item = c("1", "1", "2", "3 (A)", "3 (B)", "3", "4", "4", "5", "6", "6", "6", "Rebuild", "Rebuild", "Rebuild"),
  `Pre-registered criterion / plan` = c("Unit tests 102→118 increased, 21.9→16.9 decreased, in-band, CI across 0", "Regenerated text: 0 mismatches against Number_Trace.csv",
     "Unit test: for d_ref = 6 all three estimators classify the same events", "Mean over months of |median monthly bias| below raw for every variable (cal 1985–99 → val 2000–14)",
     "No pr month with |median bias| > 25 %", "If the primary fails, keep it and report", "Selection = 10 highest P(top 10), ties by mean rank; freeze before projections", "Report overlap with the v2.1 and v2 sets",
     "Hatch only where p_BH < 0.05 and agreement ≥ 80 %; report share before/after", "grep for drive letters returns nothing", "No warning suppression; warnings logged and explained", "DEVIATIONS numbers by placeholder substitution",
     "Fresh library from renv.lock, empty cache_R", "All unit tests pass", "Path check 0 hits; Number_Trace 100 %"),
  Actual = c("Passed (tests/test_wording.R)", "See rebuild: number-trace check", "Passed (tests/test_return_period.R)",
     paste0(if (K2$qdm_acceptance_primary$pass_A_all) "MET" else "FAILED", ": ", paste(sprintf("%s %s→%s", acc[stage == "raw", variable], f1(acc[stage == "raw", A_mean_abs], 2), f1(acc[stage == "primary", A_mean_abs], 2)), collapse = "; ")),
     paste0(if (isTRUE(a_("primary", "pr", "pass_B"))) "MET" else "FAILED", ": worst month ", a_("primary", "pr", "max_month_name"), " ", f1(a_("primary", "pr", "max_month")), "%"),
     "Done: primary per-month QDM kept; failure reported in text and DEVIATIONS F3", "Done; frozen at tag frozen-bc-rank before any projection was computed", paste0("v2.1: ", ov[1, n_common], "/10; v2: ", ov[2, n_common], "/10"),
     "Done (Fig. 6, Table S4, robust_cells_pct with/without FDR)", "0 hits", paste0("0 suppressions; ", format(K2$n_warnings_logged, big.mark = ","), " warnings logged, 0 unexplained types"), "Done (scripts/15_render_deviations.R; 42 placeholders)",
     "Done with deviation: P3M dated binaries (no Rtools), see post-hoc 6", "", ""))
rbline <- function(p) { x <- grep(p, rb, value = TRUE); if (length(x)) sub("^\\S+ \\S+ ", "", tail(x, 1)) else "not run" }
PR[13, Actual := paste0(Actual, "; ", rbline("version check"))]; PR[14, Actual := rbline("^.* tests:")]; PR[15, Actual := paste(rbline("17_check_paths:"), "|", rbline("16_check_number_trace:"))]

# ---- 4. variants ----
AV <- fread(file.path(ROOT, "sensitivity", "all_variants.csv"))
AVs <- AV[, .(n = .N), by = .(item, role)][order(item, role)]

# ---- document ----
doc <- read_docx()
ft <- function(d, w = NULL, size = 8) { x <- flextable(d); x <- fontsize(x, size = size, part = "all"); x <- font(x, fontname = "Times New Roman", part = "all"); x <- theme_booktabs(x); x <- set_table_properties(x, layout = "autofit", width = 1); x }
H <- function(t, l = 1) body_add_par(doc, t, style = paste("heading", l))
Pp <- function(t) body_add_par(doc, t, style = "Normal")
doc <- H("Fix 2 report — six remaining code issues under the pre-registered no-bias protocol (v2.2)")
doc <- Pp(paste0("Generated by analysis/scripts/20_fix2_report.R on ", format(Sys.Date(), "%d %B %Y"), ". v2.1 values are read from git tag v2-prefix (results_text/key_numbers.json); v2.2 values from the clean rebuild (results_text/key_numbers.rds). Pre-registration: analysis/PREREGISTRATION.md (tag prereg-v2), including the post-hoc section."))
doc <- H("1. Per item: before | after | numbers changed", 2); doc <- body_add_flextable(doc, ft(ITEMS, size = 7.5))
doc <- H("2. Pre-registered vs actual outcomes", 2); doc <- body_add_flextable(doc, ft(PR, size = 7.5))
doc <- H("3. Headline findings: v2.1 vs v2.2", 2)
doc <- Pp("Flags are rule-based: sign change; robustness (≥ 80 % agreement and Wilcoxon p < 0.05) changed; |relative change| ≥ 20 %.")
doc <- body_add_flextable(doc, ft(HLo, size = 7.5))
doc <- H("4. Model sets (key results under old 10, new 10, all models)", 2)
doc <- body_add_flextable(doc, ft(dt(K2$model_set_sensitivity)[, .(Set = set, Scenario = scenario, n = n_models, `Δ freq` = f1(d_freq), Robust = robust, Agree = f1(agree, 2), `Δ P %` = f1(d_P), `Δ ET0 %` = f1(d_ET0), `T25 base` = f1(T25_base), `T25 far` = f1(T25_far), `Δ wheat exp %` = f1(dE_wheat))], size = 7))
doc <- H("5. Rank stability of the selected models (entropy weights)", 2)
doc <- body_add_flextable(doc, ft(STAB[, .(Model = model, `Sel. order` = sel_order, `P(top 10)` = f1(p_top10, 3), `Mean rank` = f1(mean_rank), `90 % rank interval` = paste0(rank_q05, "–", rank_q95), L = f1(L_full, 3))]))
doc <- H("6. All variants (sensitivity/all_variants.csv)", 2)
doc <- Pp(paste0(nrow(AV), " rows. Counts by item and role:")); doc <- body_add_flextable(doc, ft(AVs))
doc <- Pp("Full listing (role: primary = pre-registered method; sensitivity = reported, not eligible to replace the primary; reference = raw/no correction):")
doc <- body_add_flextable(doc, ft(AV[, .(item, variant, role, metric, value = formatC(value, format = "g", digits = 4))], size = 6))
doc <- H("7. Clean rebuild", 2); for (l in rb) doc <- Pp(l)
doc <- H("8. Independent re-audit (agent without the fix history or earlier scores)", 2)
if (!is.null(total)) doc <- Pp(paste0("Score: ", total$score[1], " / 100, grade ", total$grade[1], ". ", total$note[1]))
if (!is.null(scores)) doc <- body_add_flextable(doc, ft(scores, size = 7.5)) else doc <- Pp("Scores not yet available.")
print(doc, target = file.path(AUD, "Fix2_Report.docx")); cat("Fix2_Report.docx written\n")
